// Extension d'essai du lot 7 (protocole 1.0) : événements, minuteries, matières, balises, unités.
let selection = 0;
let dessin = null;
let ouvertures = 0;
let enregistrements = 0;
const origines = [];

planche.sur("projet.ouvert", (d) => {
  ouvertures += 1;
  dessin = d && d.nom;
});
planche.sur("projet.enregistre", () => {
  enregistrements += 1;
});
planche.sur("selection.change", (d) => {
  selection = d.selection.length;
});
// Chaque changement du dessin est compté dans les données du projet : l'écriture se rattache au pas de l'utilisateur.
planche.sur("modele.change", async (d) => {
  origines.push(d.origine);
  if (d.origine === "annulation" || d.origine === "retablissement") {
    // Essai : après une annulation, la Planche refuse toute modification faite en réaction.
    await planche.modele.ligne([0, 0, 0], [9, 9, 9]);
    return;
  }
  const n = ((await planche.donnees.lire("projet", "changements")) || 0) + 1;
  await planche.donnees.ecrire("projet", "changements", n);
});

planche.sur("commande.etat", async () => {
  const changements = (await planche.donnees.lire("projet", "changements")) || 0;
  const etat = { changements, selection, dessin, ouvertures, enregistrements, origines: origines.slice(-6) };
  await planche.message.afficher("changements=" + changements + " selection=" + selection + " ouvertures=" + ouvertures + " enregistrements=" + enregistrements + " origines=" + etat.origines.join(","));
  return etat;
});

planche.sur("commande.rappel", async (d) => {
  const en = d && d.langue === "en";
  await planche.minuterie.dans(400, async () => {
    await planche.modele.ligne([0, 0, 2], [1, 0, 2]);
    await planche.message.afficher(en ? "Reminder: a line was drawn." : "Rappel : une ligne a été tracée.");
  });
  await planche.message.afficher(en ? "Reminder set." : "Rappel armé.");
  return true;
});

planche.sur("commande.mesurer", async () => {
  const u = await planche.unites.lire();
  const matieres = await planche.matieres.lire();
  const balises = await planche.balises.lire();
  const texte = (await planche.unites.formater(1.5)) + " · " + (await planche.unites.formater(2.25, "aire")) + " · " + matieres.length + " matière(s) · " + balises.length + " balise(s)";
  await planche.message.afficher(texte);
  return { unites: u, matieres: matieres.length, balises: balises.length };
});
